def translate(s): return ''.join(codon_tab.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def stopfree_stretches(s,f):
    t=translate(s[f:])
    out=[];start=0
    for idx,ch in enumerate(t):
        if ch=='*':
            out.append((start,idx)); start=idx+1
    out.append((start,len(t)))
    return out, t

for name,s in [('fwd',seq),('rev',rc)]:
    for f in range(3):
        st,t=stopfree_stretches(s,f)
        longest=max(st,key=lambda x:x[1]-x[0])
