comp={'A':'T','T':'A','G':'C','C':'G','N':'N'}
rc=''.join(comp[c] for c in reversed(seq))
codon_tab={}
bases='TCAG'; aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for a in bases:
    for b in bases:
        for c in bases:
            codon_tab[a+b+c]=aas[i]; i+=1
def translate(s): return ''.join(codon_tab.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))
STOPS=('TAA','TAG','TGA')

def report(name,s):
    print('=====',name)
    for p in range(len(s)-2):
        c=s[p:p+3]
        if c in STOPS:
            f=p%3
            # downstream stop-free length for each frame
            info=[]
            for g in range(3):
                # first codon boundary >= p+3 in frame g
                start=p+3
                while start%3!=g: start+=1
                j=start; n=0
                while j+3<=len(s) and s[j:j+3] not in STOPS:
                    n+=1; j+=3
                info.append((g,n,s[start:start+45]))
            # upstream: ORF from nearest ATG
            up=0
            j=p-3
            while j>=0 and s[j:j+3] not in STOPS:
                if s[j:j+3]=='ATG': up=(p-j)//3; break
                up=(p-j)//3
                j-=3
            best=max(info,key=lambda x:x[1])
            if best[1]>=60 and up<60:
                print(f'stop {c} at {p} frame{f} upORF~{up}aa; downstream frame{best[0]}: {best[1]} codons  ctx={s[p:p+30]}...')
report('fwd',seq)
report('rev',rc)
"}

